# Candidate (B1) for TASK-BANK-023 (account_id_uuid_type)
def build_request(data):
    return {
        'path': '/v2/banking/account_id_uuid_type/task-bank-023',
        'body': {
            'uuid_transfer': {
                'amount_subunits': int(data['amount_cents']),
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': data['destination'],
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'Idempotency-Key': data['idempotency_key']
        }
    }

def process_wire(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
